import { getFontMontserrat } from "../../../assets/fonts/FontMontserrat"
import "@fontsource/montserrat"
import "@fontsource/montserrat/600.css" 
import "@fontsource/montserrat/400.css" 
import Hide from "../../../locust/composables/Hide"
import { Center } from "../../../locust/composables/Center"

const VERSION : number = 1

export default ( props : {
    logo ?: any, 
}) => <HeaderServiceAreaQuoteV1 {...props}/>

export const HeaderServiceAreaQuoteV1 = ( props : {
    logo ?: any, 
}) => {
    const space : number = 20
    const height : number = 70
    return (
        <div style={{ height : height, backgroundColor : 'white', width : '100%'}}> 
            <Hide on={850}>
                { props.logo && 
                    <GridRow height={height} style={{ float : 'left'}}>
                        <div style={{ height, backgroundColor : '', marginTop : 8 }}>
                            <img src={props.logo} style={{ marginLeft : 10 }} width={200} />
                        </div>
                    </GridRow>
                }
                
                <GridRow height={height} style={{ float : 'right'}}>
                    <IconSAQ w={130 + space } icon={ Quote } title="Get a Quote" subtitle="Contact Us"/>
                </GridRow>
                <GridRow height={height} style={{ float : 'right'}}>
                    <IconSAQ w={170 + space } icon={ Area } title="Area" subtitle="BOISE | NAMPA | MERIDIAN"/>
                </GridRow>
                <GridRow height={height} style={{ float : 'right'}}>
                    <IconSAQ w={240 + space } icon={ Service } title="Services" subtitle="REPAIR | MAINTENANCE | CUSTOM WORK"/>
                </GridRow>
            </Hide>
            <Hide b4={850}>
                <GridRow height={height} style={{ float : 'left'}}>
                    <div style={{ position : 'absolute', height, backgroundColor : '', marginTop : 8 }}>
                        <img src={props.logo} style={{ marginTop : -30, marginLeft : 10 }} width={150} />
                    </div>
                </GridRow>

                <GridRow height={height} style={{ position : 'absolute', right : 0 }}>
                    <IconSAQ w={130 + space } icon={ Quote } title="Get a Quote" subtitle="Contact Us"/>
                </GridRow>
                
            </Hide>
        </div>
    )
}

export const IconSAQ = ( props : {
    icon ?: any,
    height ?: number, 
    title ?: string, 
    subtitle ?: string, 
    w ?: number
}) => {

    const show : boolean = false
    const height : number = props.height ? props.height : 50

    return <>
        
        <div style={{ display : 'inline-block', width : props.w }}>
            <div style={{ width : 40, display : 'inline-block', height }}>
                <GridRow height={height}>
                    <img src={ props.icon }/>
                </GridRow>
            </div>
            <div style={{ width : `calc(100% - 40px)`, display : 'inline-block', height, ...getFontMontserrat(), textTransform : 'uppercase' }}>
                <div style={{ display : 'inline-block', height : height/2, width : '100%', fontWeight : 600, fontSize : 12, backgroundColor : !show ? '' : 'red' }}>
                    <GridRow align="bottom" height={height/2}>{props.title}</GridRow>
                </div>
                <div style={{ display : 'inline-block', height : height/2, width : '100%', fontWeight : 400, fontSize : 9, backgroundColor :  !show ? '' : 'blue' }}>
                    <GridRow align="top" height={height/2}>{props.subtitle}</GridRow>
                </div>
            </div>
        </div>
        
        
        
    </>
}