import React from "react";
import "./Navbar.css";
import { Link } from "gatsby";
import GridRow from "../../../locust/composables/GridRow";
import { getFontPoppins } from "../../../assets/fonts/FontPoppins";
import Hide from "../../../locust/composables/Hide";
import { Center } from "../../../locust/composables/Center";


const VERSION : number = 3 

export default ( props : { 
    links : { href ?: string, onClick ?: ()=> void }[], 
    sx ?: { container ?: any },
    color ?: string, 
}) => {

    const color : string = props.color ? props.color : 'white'
    const height : number = 60

    return (
        <>
            <div style={{  height : height, backgroundColor : '', fontWeight : 600 }}>

                <Hide on={850}>
                    <div style={{ textAlign : 'left'}}>
                        <GridRow height={height}>
                            {props.links.map(( item : any, index : number )=>{
                                return <div key={index} style={{ ...getFontPoppins(), cursor : 'pointer',  marginLeft : 20, marginRight : 20, display : 'inline-block', ...props.sx?.container, color }}>
                                    { item.href && <Link style={{ textDecoration : 'none',  color }} to={item.href}> 
                                        {item.value}
                                    </Link>}
                                    { item.onClick && <div onClick={item.onClick}> 
                                        {item.value}
                                    </div>}
                                </div>
                            })}
                        </GridRow>
                    </div>
                </Hide>
                <Hide b4={850}>
                    <Center>
                        <div style={{ display : 'inline-block', backgroundColor : '', width : 288  }}>
                            <GridRow height={height}>
                                {props.links.map(( item : any, index : number )=>{
                                    return <div key={index} style={{ ...getFontPoppins(), cursor : 'pointer', marginLeft : 10, marginRight : 10,  display : 'inline-block', ...props.sx?.container, color }}>
                                        { item.href && <Link style={{ textDecoration : 'none',  color }} to={item.href}> 
                                            {item.value}
                                        </Link>}
                                        { item.onClick && <div onClick={item.onClick}> 
                                            {item.value}
                                        </div>}
                                    </div>
                                })}
                            </GridRow> 
                        </div>
                    </Center>
                </Hide>
            </div>
        </>
    );
};



