const R5Gallery1280 = () => {

    const size : string = 'min(calc(calc(calc(100vw) / 5) - 13px),194px)'
    const sizeS : string = 'max(calc(calc(calc(100vw) / 3) - 15px),80px)'
    const sizeMin : string = 'calc(300px / 3)'


    return (
        <>
            <div style={{ width : '100%', textAlign : 'center'}}>
                <div {...css({ 
                    display : 'inline-block', 
                    minWidth : 350, 
                    overflow : 'hidden', 
                    width : '100vw', 
                    maxWidth : 1020, 
                    backgroundColor : '', 
                    minHeight : 100,
                    [on(350)] : {
                        overflow : 'hidden', 
                        backgroundColor : 'red',
                        maxWidth : 300,
                        marginLeft : 0,
                        marginRight : 0, 
                        paddingLeft : 0, 
                        paddingRight : 0, 
                    }
                 })}>
                    { getEmpty(15).map(()=><div
                        {...css({  
                            display : 'inline-block', 
                            width : size, 
                            height : size, 
                            margin: 5,
                            backgroundColor : 'whitesmoke',
                            [ on(600) ]:{
                                width : sizeS, 
                                height : sizeS, 
                            },
                            [ on(350) ]:{
                                width : sizeMin, 
                                height : sizeMin, 
                            }
                        })}
                    />)}
                </div>
            </div>
            
        </>
    )
}

