import React from "react"
import { sixFeaturesCardsData } from "./SixFeaturesCardsExample"
import { Fade } from "react-reveal";
import "./SixFeaturesCards.css";
import { FACEBOOK_BLACK } from "../../../assets/colors/Colors";



export default(props : { 
    color ?: string, 
    shadowColor ?: string, 
    items : { title : string, subtitle : string, imgsrc ?: string, icon ?: any   }[] 
}) => <SixFeaturesCardsV1 {...props}/>

export const SixFeaturesCardsV1 = ( props : { 
    color ?: string, 
    shadowColor ?: string, 
    items : { title : string, subtitle : string, imgsrc ?: string, icon ?: any  }[] 
}) => {

    const color : string = props.color ? props.color : FACEBOOK_BLACK
    const shadowColor : string = props.shadowColor ? props.shadowColor : props.color ? props.color : FACEBOOK_BLACK
    return (
        <>
            <div className="SixFeaturesCards">
                <div className="SixFeaturesCards-inner">
            
                    {props.items.map((item : any , index) => (
                        <Fade delay={index * 200} bottom>
                            <div key={index} className="SixFeaturesCards-item" style={{ boxShadow : `0 4px 20px -6px ${shadowColor}` }}>
                                { item.imgsrc && 
                                    <Fade delay={(index * 200) + 400 } bottom>
                                        <img  src={item.imgsrc} height={50} alt="" style={{ minHeight : 80, marginBottom : 20, backgroundColor : '',...item.style }} />
                                    </Fade>
                                }
                                { item.icon && 
                                    <Fade delay={(index * 200) + 400 } bottom>
                                        { item.icon }
                                    </Fade>
                                }
                                <h1 style={{ color }}>{item.title}</h1>
                                <p>{item.subtitle}</p>
                            </div>
                        </Fade>
                    ))}
                </div>
            </div>
        </>
    )
}